/// `enum :role, %i[ member administrator ]`
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum Role {
    #[default]
    Member = 0,
    Administrator = 1,
}

impl Role {
    pub fn name(self) -> &'static str {
        match self {
            Role::Member => "member",
            Role::Administrator => "administrator",
        }
    }

    pub fn from_name(name: &str) -> Option<Self> {
        match name {
            "member" => Some(Role::Member),
            "administrator" => Some(Role::Administrator),
            _ => None,
        }
    }
}

/// `enum :status, %i[ active deactivated banned ], default: :active`
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum Status {
    #[default]
    Active = 0,
    Deactivated = 1,
    Banned = 2,
}

impl Status {
    pub fn name(self) -> &'static str {
        match self {
            Status::Active => "active",
            Status::Deactivated => "deactivated",
            Status::Banned => "banned",
        }
    }

    pub fn from_name(name: &str) -> Option<Self> {
        match name {
            "active" => Some(Status::Active),
            "deactivated" => Some(Status::Deactivated),
            "banned" => Some(Status::Banned),
            _ => None,
        }
    }
}

macro_rules! integer_enum_sql {
    ($ty:ty, $($variant:path = $value:literal),+) => {
        impl ToSql for $ty {
            fn to_sql(&self) -> rusqlite::Result<ToSqlOutput<'_>> {
                Ok(ToSqlOutput::from(*self as i64))
            }
        }

        impl FromSql for $ty {
            fn column_result(value: ValueRef<'_>) -> FromSqlResult<Self> {
                match value.as_i64()? {
                    $($value => Ok($variant),)+
                    other => Err(FromSqlError::OutOfRange(other)),
                }
            }
        }
    };
}

integer_enum_sql!(Role, Role::Member = 0, Role::Administrator = 1);
integer_enum_sql!(Status, Status::Active = 0, Status::Deactivated = 1, Status::Banned = 2);

