    fn recognize_by_scanning(method: &Method, path: &str) -> Result<Option<(&'static Route, ParamMap)>> {
        let verb = if *method == Method::HEAD { &Method::GET } else { method };
        for route in routes().iter().filter(|route| route.verb == *verb) {
