///
/// `framed_page!(c, StatusCode::OK, |ctx| rooms::Show { ctx, show: &show }).await`
macro_rules! framed_page {
    ($c:expr, $status:expr, |$ctx:ident| $page:expr) => {
        $crate::controllers::presenters::view_context::page_or_frame(
            $c,
            $status,
